  String name;
  void eat() { System.out.println(name + " eats"); }
}
class Dog extends Animal {
  void bark() { System.out.println(name + " barks"); }
}

class Dog extends Animal {
  @Override
  void speak() {
    System.out.println(name + " says woof");
  }
}

class Dog extends Animal {
  Dog(String name) {
    super(name); // parent constructor sets the name
  }
}

interface Flyable {
  void fly(); // no body — just the promise
}
class Bird implements Flyable {
  public void fly() {
    System.out.println("flap flap");
  }
}

if (a instanceof Dog) {
  Dog d = (Dog) a; // safe now
  d.bark();
}
